"""Short regional widebody freight, generated by the existing board worker.

Cargo is fictional consolidated crated components, not outsize-load certification.
No urgent flag: these jobs must not enter the separate urgent booking/payment flow.
"""
import json
import random

HEAVIES = {'A306F', 'MD11F', 'B77F', 'B748F', 'B763F', 'B742F'}
DAILY_LIMIT = 36
HANDLING_POINTS = 80
# Explicit civilian candidates: airport data alone does not identify military fields.
# This is a routing pool, not a guarantee of stand, handling or performance suitability.
DESTINATIONS = set('''KCVG KCMH KIND KSDF KSTL KDTW KCLE KBNA KATL KCLT KMEM
KJAX KMCO KTPA KSFB KMIA KFLL KRSW KPBI KORD KRFD KMSP KDEN KCOS
KSEA KPDX KGEG KSFO KOAK KSJC KSMF KLAX KONT KSAN KLAS KPHX
KJFK KEWR KPHL KBWI KIAD KBOS KPIT CYUL CYYZ CYOW CYHM
PANC PAFA PAKN LIMC LIMF LIME LIPE LIPZ LIRP LIRF LIRN
LFML LFLL LSGG LSZH EDDM EDDS EDDF EDDK EDDH EDDL EHAM EBBR
EGLL EGSS EGNX EGCC EGPK EGPH EIDW LEMD LEBL LPPT LJLJ LOWW LKPR
VHHH ZGGG ZGOW ZGKL ZJHK ZGHA ZSAM RCTP OMDW OMDB OMAA OOMS OBBI OTHH OEMA OERK
MYNN TJSJ TNCM TTPP MKJP MMMX MMUN
KTYS KLEX KDAY KTOL KFWA KSBN KGRR KLAN KROC KBUF KSYR KALB
KRIC KORF KRDU KGSO KGSP KCHS KSAV KCAE KBHM KHSV KCHA KJAN
KPNS KMOB KMSY KBTR KLFT KSHV KLRD KSAT KAUS KIAH KHOU KDFW KAFW
KOKC KTUL KICT KOMA KDSM KCID KMLI KMKE KATW KDLH KFAR
KRNO KBOI KSLC KABQ KELP KTUS KPSP KBFL KFAT KSBP KMFR KEUG
CYMX CYQB CYHZ CYQM CYWG CYQR CYYC CYEG CYVR CYYJ CYXX
PABE PAJN PAKT LPPR LEMG LEZL LEVC LEBB LEZG LEBG
LFSB LFST LFBT LFBO LFBD LFRN LFRS LFQQ EDDP EDDB EDDV EDDN
EBLG EBCI EHBK EHEH EHRD EDDR EDSB LOWL LOWS LKMT LKTB
LZIB LHBP LROP LRSB LQSA LDZA LDSP LDDU LIPX LIPQ LIBD LIBR
EGNX EGHH EGBB EGNM EGNT EGPD EGPE EGPF EGAA EICK EINN
EKBI EKCH ESGG ESSA ENGM ENBR ENZV ENVA EFHK
ZGSZ ZGZH ZGNN ZHCC ZHHH ZSNJ ZSHC ZSNB ZSQZ ZSFZ
RJAA RJTT RJGG RJBB RJOO RJFF RKSI RKSS RKPK RPLC RPLL
WSSS WMKK WMKP WMKJ VTBS VTBD VTCC WIII WARR
MTPP MDPC MDSD TJBQ TIST TISX TAPA TKPK TFFR TFFF TBPB
MMMD MMTJ MMPR MMGL MMQT MMMY MMTO'''.split())
SCENARIOS = (
    ('factory', 'Factory restart', 'Crated generator components and production-line spares',
     'A receiving factory is preparing a maintenance restart. This consolidated shipment brings replacement generator components and line spares together on one regional freighter sector.',
     'Keep the numbered crates together for the receiving maintenance team.'),
    ('maintenance', 'Maintenance supply run', 'Crated engine modules, tooling and maintenance spares',
     'A nearby maintenance station is consolidating its next work package. Engine modules, tooling and spares travel together so the team can receive the equipment in one delivery.',
     'Protect transport cradles and keep tooling cases secured separately from components.'),
    ('power', 'Power restoration supplies', 'Crated electrical components, cable and repair equipment',
     'A regional repair depot is staging equipment for power-restoration work. A short air transfer moves a consolidated load to the receiving team without turning this into a long-haul assignment.',
     'Distribute dense cable and equipment crates across suitable load positions.'),
    ('machinery', 'Industrial transfer', 'Crated machinery subassemblies and industrial spares',
     'An onward transport team needs a consolidated machinery shipment at an inland airport. PAC carries the air leg; the receiving team handles the final road transfer.',
     'Check crate identification and keep matching subassemblies on the same manifest.'),
)


def generate(ctx, con, day, here, used, next_id, day_end, pending=()):
    """Cap issuance per day across open/booked/completed jobs; avoid duplicate routes."""
    existing = []
    for row in con.execute('SELECT data FROM jobs WHERE day=?', (day,)):
        job = json.loads(row[0])
        if job.get('short_heavy'):
            existing.append(job)
    remaining = max(0, DAILY_LIMIT - len(existing))
    if not remaining:
        return []
    fleet = ctx['FLEET']
    heavy = {k:v for k,v in fleet.items() if k in HEAVIES and not v.get('retired')}
    if not heavy:
        return []
    rng = random.Random(day + '|short-heavy-v1')
    origins = {}
    for row in con.execute("SELECT type,location FROM airframes WHERE status='Available'"):
        if row['type'] in heavy:
            origins.setdefault(row['location'],set()).add(row['type'])
    locations = sorted(origins)
    rng.shuffle(locations)
    locations.sort(key=lambda x:x != here)
    candidates = []
    for loc in locations:
        o=ctx['airport_obj'](loc)
        if not o or not o.get('rwy_ft'):
            continue
        routes=[]
        for airport in ctx['AIRPORTS'].values():
            if airport['icao'] not in DESTINATIONS:
                continue
            if airport.get('size') not in ('L','M') or not airport.get('rwy_ft'):
                continue
            if abs(airport['lat']-o['lat']) > 6:
                continue
            dist=ctx['gc_distance_nm'](o['lat'],o['lon'],airport['lat'],airport['lon'])
            if not 100 <= dist <= 300:
                continue
            d=ctx['airport_obj'](airport['icao'])
            if not d or not d.get('rwy_ft'):
                continue
            runway=min(o['rwy_ft'],d['rwy_ft'])
            fits=[k for k,v in heavy.items() if v.get('min_rwy_ft',999999)<=runway and v.get('range_nm',0)>=dist*1.05 and v.get('max_payload_lbs',0)>=65000]
            if not any(k in origins[loc] for k in fits):
                continue
            routes.append((o,d,dist,fits))
        rng.shuffle(routes)
        candidates.append(routes)
    seen={(j['origin']['icao'],j['destination']['icao']) for j in existing+list(pending)}
    jobs=[]
    # Round robin gives different stations a share before taking another route.
    while any(candidates) and len(jobs)<remaining:
        for routes in candidates:
            while routes:
                o,d,dist,fits=routes.pop()
                route=(o['icao'],d['icao'])
                if route in seen:
                    continue
                seen.add(route)
                lead=next(k for k in fits if k in origins[o['icao']])
                payload=min(110000,int(heavy[lead]['max_payload_lbs']*.7/500)*500)
                payload=max(65000,payload)
                fits=[k for k in fits if heavy[k]['max_payload_lbs']>=payload]
                # Always include the type that is actually present; no arbitrary top-four truncation.
                key,title,cargo,story,note=SCENARIOS[(len(existing)+len(jobs))%len(SCENARIOS)]
                jid=next_id(con,used)
                if not jid:
                    return jobs
                block=round(45+dist/min(heavy[k]['cruise_ktas'] for k in fits)*60*1.05)
                base=int(round((dist*.14+payload/1000*1.2)/10)*10)
                jobs.append({'id':jid,'title':f"{title}: {o.get('city') or o['icao']} to {d.get('city') or d['icao']}",
                    'category':'Heavy lift','priority':'Standard','job':True,'job_kind':'cargo','job_type':'Short-haul heavies',
                    'short_heavy':True,'scenario':key,'types_only':True,'origin':o,'destination':d,'aircraft':fits,
                    'cargo':cargo,'payload_lbs':payload,'distance_nm':round(dist),'target_block_min':block,'expires':day_end,
                    'reward':base+HANDLING_POINTS,'handling_points':HANDLING_POINTS,
                    'briefing':story+f' {round(dist)} nm with {payload:,} lb of consolidated freight. Routine delivery: no fixed arrival deadline. Estimated block time includes ground time.',
                    'handling':{'label':'Short-haul heavies · crated components','notes':[note,
                        'Plan this as multiple crated components, not a single oversized item. Verify actual package dimensions, cargo-door clearance, floor loading and restraint limits in your aircraft load-planning tools.',
                        'Runway length, range and nominal payload were screened from PAC data. Confirm current conditions and aircraft performance in dispatch.']}})
                break
            if len(jobs)>=remaining:
                break
    return jobs
